FILE src/rules/types.ts — widen `derivedGrant` so a NAMED answer->record relation can be stated.
FIND (unique — the only occurrence of this comment):
    /** How the answer becomes a record id: `initiate-benefit-` + `chalice`. */
    prefix?: string;
    suffix?: string;
  };
REPLACE:
    /** How the answer becomes a record id: `initiate-benefit-` + `chalice`. */
    prefix?: string;
    suffix?: string;
    /**
     * …for the answers that do not TRANSFORM into an id. A gunslinger way's initial deed is NAMED,
     * not derived — `way-of-the-drifter` -> `into-the-fray` — so no prefix/suffix can reach it, and
     * Slinger's Readiness ("You gain the initial deed for the way you selected with Gunslinger
     * Dedication") delivered nothing at all. Keys are the granting feat's own `choice` answer values.
     * Wins over prefix/suffix when present; an answer with no entry grants nothing.
     */
    map?: Record<string, string>;

FILE src/rules/derive.ts — teach the derivedGrant reader to honour `map`.
FIND (unique — the only template literal built from d.prefix/d.suffix in the repo):
    const id = `${d.prefix ?? ''}${answer.replace(/^aon-/, '')}${d.suffix ?? ''}`;
REPLACE:
    const bare = answer.replace(/^aon-/, '');
    // A NAMED relation (`map`) beats a derived one: a gunslinger way's initial deed shares no stem
    // with the way's id, so prefix/suffix could never reach it.
    const id = d.map ? (d.map[bare] ?? '') : `${d.prefix ?? ''}${bare}${d.suffix ?? ''}`;

